Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
// LUOGU_RID: 95322299
#include<bits/stdc++.h>
#define reg register
#define int long long
using namespace std;
inline int read(){
	reg int k=1,x=0;char ch=getchar();
	while (ch<'0'||ch>'9'){if(ch=='-') k=-1;ch=getchar();}
	while (ch>='0'&&ch<='9') x=(x<<3)+(x<<1)+ch-48,ch=getchar();
	return k*x;
}
inline int cmin(reg int x,reg int y){return x<y?x:y;}
inline int cmax(reg int x,reg int y){return x>y?x:y;}
const int N=2e6+10,Mod=1e9+7,mod=998244353,B=1000000;
int n,idx,ans,sum[10];
vector<int> v[10];
inline int MOD(reg int x){return (x%mod+mod)%mod;}
inline void dfs1(reg int x,reg int len){
	++idx,v[len].push_back(MOD(idx-x)); (sum[len]+=v[len].back())%=Mod;
	if (len==6) return; for (reg int i=0;i<10;i++) dfs1(x*10+i,len+1);
} 
inline void dfs2(reg int x){ if (x>n) return;
	if (x*B+(B-1)<=n&&x*B*10>n){ reg int now=idx;
		for (reg int i=0,mul=1;i<=6;i++,mul=mul*10){ reg int sz=v[i].size();
			reg int d=MOD(now-x*mul),pos=lower_bound(v[i].begin(),v[i].end(),mod-d)-v[i].begin();
			ans=(ans+d*sz+sum[i]-mod*(sz-pos))%Mod; idx+=sz;
		} return;
	}idx++;ans=(ans+MOD(idx-x))%Mod;
	for (reg int i=0;i<10;i++) dfs2(x*10+i); 
}
signed main(){
	n=read(); dfs1(0,0); for (reg int i=0;i<=6;i++) sort(v[i].begin(),v[i].end());
	idx=0; for (reg int i=1;i<=9;i++) dfs2(i); printf("%lld",(ans+Mod)%Mod);
	return 0;
} 
